mapper.select:
SELECT id, user_id, knowledge_base_id, title, created_at, updated_at, deleted_at
FROM chat_session
WHERE user_id = #{userId}
  AND knowledge_base_id = #{knowledgeBaseId}
  AND deleted_at IS NULL
ORDER BY updated_at DESC, id DESC

mapper.update:
UPDATE chat_session
SET title = #{title}
WHERE id = #{id}
  AND deleted_at IS NULL
